// Exact arithmetic on values (spec 0022, "Exact results"; GLOSSARY: Aggregation, Comparison, Attainment). A value is
// read from its shortest text, the way it came from the database, as a fraction of two BigInts; sums, differences,
// changes and Attainment are worked out on those without loss, and only the result becomes a double, the one nearest
// to it. Adding or dividing doubles gives 0.30000000000000004 for 0.1 + 0.2 and 0.19999999999999998 for 0.3 − 0.1;
// this gives 0.3 and 0.2. Pure, so the browser computes the same numbers.
//
// BigInt(…) rather than literals such as 10n: the app's TypeScript targets a version before BigInt literals.
const [ZERO, ONE, TWO, TEN, HUNDRED] = [BigInt(0), BigInt(1), BigInt(2), BigInt(10), BigInt(100)];
const TEXT = /^(-?)(\d+)(?:\.(\d+))?(?:e([+-]\d+))?$/;

/** A number held exactly as `num / den`, `den` positive. */
export type Fraction = { num: bigint; den: bigint };

/** A finite value as digits and how many of them are decimals: 1.25 is 125 and 2, 1e-7 is 1 and 7. */
export function scaled(v: number): { digits: bigint; places: number } {
  const [, sign, whole, decimals = "", exp = "0"] = TEXT.exec(String(v))!;
  const places = decimals.length - Number(exp);
  const digits = BigInt(`${sign}${whole}${decimals}`);
  return places >= 0 ? { digits, places } : { digits: digits * TEN ** BigInt(-places), places: 0 };
}

/** A finite value exactly as its shortest text says: 0.1 is 1/10, not the double nearest to it. */
export function fractionOf(v: number): Fraction {
  const { digits, places } = scaled(v);
  return { num: digits, den: TEN ** BigInt(places) };
}

/** How many bits a whole number's size takes (0 has one). */
export const bitLength = (n: bigint) => (n < ZERO ? -n : n).toString(2).length;
const TWO_53 = TWO ** BigInt(53);

/** The double nearest to num / den (den positive), ties to even: the quotient is taken to 53 bits with the
 * remainder deciding the last one, then scaled by a power of two, which is exact. Values Ziffr keeps are far from
 * the edges of the double range, so no result is subnormal or infinite. */
export function nearestDouble(num: bigint, den: bigint): number {
  if (num === ZERO) return 0;
  const negative = num < ZERO;
  const a = negative ? -num : num;
  // A first guess for the power of two that brings the quotient to 53 bits; one more when it lands on 54.
  let e = bitLength(a) - bitLength(den) - 53;
  const divide = (shift: number) => {
    const [top, by] = shift < 0 ? [a << BigInt(-shift), den] : [a, den << BigInt(shift)];
    return [top / by, top % by, by];
  };
  let [q, r, d] = divide(e);
  if (q >= TWO_53) [q, r, d] = divide(++e);
  if (TWO * r > d || (TWO * r === d && (q & ONE) === ONE)) q++;
  const x = Number(q) * 2 ** e;
  return negative ? -x : x;
}

/** The sum of the values divided by `count`, as the double nearest to the exact result. A value that is not finite
 * has no exact sum: the result is then what adding doubles gives (NaN or an infinity), which shows as no value. */
export function exactTotal(values: readonly number[], count: number): number {
  if (!values.every((v) => Number.isFinite(v))) return values.reduce((a, v) => a + v, 0) / count;
  const parts = values.map(scaled);
  const places = Math.max(...parts.map((p) => p.places));
  const sum = parts.reduce((a, p) => a + p.digits * TEN ** BigInt(places - p.places), ZERO);
  return nearestDouble(sum, TEN ** BigInt(places) * BigInt(count));
}

/** A number written as digits with an optional decimal part ("12", "0.5"), exactly. */
export function fractionOfText(text: string): Fraction {
  const [, sign, whole, decimals = ""] = TEXT.exec(text)!;
  return { num: BigInt(`${sign}${whole}${decimals}`), den: TEN ** BigInt(decimals.length) };
}

/** A fraction in lowest terms: numerator and denominator divided by their greatest common divisor. */
export function lowestTerms(a: Fraction): Fraction {
  let [x, y] = [a.num < ZERO ? -a.num : a.num, a.den];
  while (y) [x, y] = [y, x % y];
  return x > ONE ? { num: a.num / x, den: a.den / x } : a;
}

/** a + b on fractions. */
export const plus = (a: Fraction, b: Fraction): Fraction => ({ num: a.num * b.den + b.num * a.den, den: a.den * b.den });
/** a − b on fractions. */
export const minus = (a: Fraction, b: Fraction): Fraction => ({ num: a.num * b.den - b.num * a.den, den: a.den * b.den });
/** a × b on fractions. */
export const times = (a: Fraction, b: Fraction): Fraction => ({ num: a.num * b.num, den: a.den * b.den });
/** a ÷ b on fractions, the denominator kept positive; b is not 0. */
export const over = (a: Fraction, b: Fraction): Fraction => (b.num < ZERO ? { num: -a.num * b.den, den: a.den * -b.num } : { num: a.num * b.den, den: a.den * b.num });
/** The double nearest to a fraction. */
export const nearest = (a: Fraction) => nearestDouble(a.num, a.den);
const times100 = (a: Fraction): Fraction => ({ num: a.num * HUNDRED, den: a.den });
const plus100 = (a: Fraction): Fraction => ({ num: a.num + HUNDRED * a.den, den: a.den });
const finite = (...vs: number[]) => vs.every((v) => Number.isFinite(v));

/** a − b, exactly on the values' text, as the nearest double: 0.3 − 0.1 is 0.2. Not finite in, not finite out. */
export function difference(a: number, b: number): number {
  return finite(a, b) ? nearest(minus(fractionOf(a), fractionOf(b))) : a - b;
}

/** The change from `previous` to `current` in % of the size of `previous`, (current − previous) ÷ |previous| × 100,
 * exactly, as the nearest double: from −10 to −5 is +50 %. Null from 0, where no share means anything. */
export function changePct(current: number, previous: number): number | null {
  if (previous === 0) return null;
  if (!finite(current, previous)) return ((current - previous) / Math.abs(previous)) * 100;
  const p = fractionOf(previous);
  return nearest(times100(over(minus(fractionOf(current), p), { num: p.num < ZERO ? -p.num : p.num, den: p.den })));
}

/** a ÷ b × 100, exactly, as the nearest double: 0.1 of 0.3 is 33.333333333333336 %, 1 of 3 the same. `b` is not 0. */
export function percentOf(a: number, b: number): number {
  return finite(a, b) ? nearest(times100(over(fractionOf(a), fractionOf(b)))) : (a / b) * 100;
}

/** 100 % plus `ahead` in steps of |`size`|, 100 + ahead ÷ |size| × 100, exactly, as the nearest double, with `ahead`
 * itself the exact difference `a − b`: 0.1 over 0.2 is 50 %, not 49.99…. `size` is not 0. */
export function distancePct(a: number, b: number, size: number): number {
  if (!finite(a, b, size)) return 100 + ((a - b) / Math.abs(size)) * 100;
  const s = fractionOf(size);
  return nearest(plus100(times100(over(minus(fractionOf(a), fractionOf(b)), { num: s.num < ZERO ? -s.num : s.num, den: s.den }))));
}

/** Whether the change from `previous` to `current` is larger in size than `limit` % of the size of `previous`, decided
 * exactly: a change of exactly the limit is not larger, however the doubles round. `previous` is not 0. */
export function changeBeyond(current: number, previous: number, limit: number): boolean {
  if (!finite(current, previous, limit)) return Math.abs(((current - previous) / Math.abs(previous)) * 100) > limit;
  const [d, p, l] = [minus(fractionOf(current), fractionOf(previous)), fractionOf(previous), fractionOf(limit)];
  const size = (x: bigint) => (x < ZERO ? -x : x);
  // |d| × 100 > l × |p|, with every denominator multiplied out.
  return size(d.num) * HUNDRED * l.den * p.den > l.num * size(p.num) * d.den;
}

src/aggregations-snapshots.test.ts.source:
// A Snapshot's values against the reference on the hand-made cases (spec 0022; GLOSSARY: Snapshot, Display
// Period): kept as of its period's last day and combined as of the day after, for every Snapshot period.
import { describe, expect, it } from "vitest";
import { dayAfter, shownSeries, type DisplayPeriod } from "./display-periods";
import { dataAsOf } from "./snapshot-periods";
import { canvas, metric } from "./test/fixtures";
import { dayOf, spanEnd, spanStart, textOf } from "./test/reference/calendar";
import { everyCase, MID } from "./test/reference/cases";
import { AGGREGATIONS, longer, seriesMismatch } from "./test/reference/check";
import { nextDay, referenceKept, referenceSeries } from "./test/reference/combine";

describe("a Snapshot's day", () => {
  it("shows what the reference keeps and combines as of the day after the Snapshot period, for every Snapshot period", () => {
    for (const { own, ys, c } of everyCase()) {
      if (c.alignTo) continue;
      for (const aggregation of AGGREGATIONS) {
        const m = metric({ period: own, aggregation });
        for (const kind of ["week", "month", "quarter", "half", "year"] as const) {
          const end = textOf(spanEnd(spanStart(dayOf(c.points[Math.floor(c.points.length / 2)]?.period ?? MID), kind, ys), kind, ys));
          // As snapshots.ts reads one: the values of the Metric periods over by the period's last day, on the day after.
          const kept = { ...dataAsOf(canvas([m], { revenue: c.points }, { yearStart: ys }), end), today: dayAfter(end) };
          for (const display of longer(own)) {
            const shown = shownSeries(m, kept, display as DisplayPeriod);
            const ref = referenceSeries(referenceKept(c.points, own, end, ys), own, display, aggregation, { yearStart: ys, today: nextDay(end) });
            const where = `${c.name}: ${own} by ${display}, ${aggregation}, Snapshot of the ${kind} to ${end}, ${ys}`;
            if (aggregation === "none") {
              expect(shown.combined, where).toBe(false);
              continue;
            }
            expect(seriesMismatch({ ok: true, points: shown.points }, ref, 0), where).toBeNull();
          }
        }
      }
    }
  });
});

src/aggregations-compare.test.ts.source:
// Comparisons against the reference on the hand-made cases (spec 0022; GLOSSARY: Comparison, Aggregation): both
// values of every Comparison, to date and in full, for every source Period, Aggregation and Fiscal Year start.
import { describe, expect, it } from "vitest";
import { compare, resolverFrom } from "./compare";
import type { Span, YearStart } from "./periods";
import { metric } from "./test/fixtures";
import { dayOf, monthsLater, spanEnd, spanStart, textOf } from "./test/reference/calendar";
import { at, everyCase, LATER, starts, type Source } from "./test/reference/cases";
import { AGGREGATIONS, valueMismatch } from "./test/reference/check";
import { referenceSeries, referenceValueOver } from "./test/reference/combine";
import { referenceChangeOf } from "./test/reference/change";
import { exactOf, exactText, fitsDigits, isNearestDouble } from "./test/reference/exact";
import type { Aggregation, Point } from "./types";

describe("Comparisons against the reference", () => {
  /** What the reference says a Comparison's two values are. */
  function expected(points: Point[], own: Source, aggregation: Aggregation, key: string, full: boolean, ys: YearStart) {
    const latest = [...points].sort((a, b) => (a.period < b.period ? -1 : 1)).at(-1)!.period;
    const last = dayOf(latest);
    const one = (d: number) => referenceValueOver(points, aggregation, textOf(d), textOf(d), 1);
    const grain = ({ dod: "day", wow: "week", mom: "month", qoq: "quarter", hoh: "half" } as Record<string, Span>)[key];
    if (key === "prev" || grain === own) return [one(last), one(spanStart(last - 1, own, ys))];
    if (key === "yoy") return [one(last), one(own === "week" ? last - 364 : monthsLater(last, 12 * -1))];
    if (aggregation === "none") return null;
    const gStart = spanStart(last, grain, ys);
    let s = gStart;
    let series;
    if (full) {
      const complete = spanEnd(gStart, grain, ys) <= spanEnd(last, own, ys);
      s = complete ? gStart : spanStart(gStart - 1, grain, ys);
      series = referenceSeries(points, own, grain, aggregation, { yearStart: ys, today: textOf(spanEnd(last, own, ys) + 1) });
    } else {
      series = referenceSeries(points, own, grain, aggregation, { yearStart: ys, today: LATER, alignTo: latest });
    }
    const value = (start: number) => (series.ok ? (series.spans.find((x) => x.period === textOf(start))?.value ?? null) : null);
    return [value(s), value(spanStart(s - 1, grain, ys))];
  }

  it("compares the same values as the reference, for every Comparison, to date and in full", () => {
    for (const { own, ys, c } of everyCase()) {
      if (!c.points.length) continue;
      for (const aggregation of AGGREGATIONS) {
        const m = metric({ period: own, aggregation });
        const r = resolverFrom([m], { revenue: c.points });
        for (const full of [false, true]) {
          for (const cmp of compare(m, r, { yearStart: ys, full })) {
            const where = `${c.name}: ${own}, ${cmp.key}${full ? " in full" : " to date"}, ${aggregation}, ${ys}`;
            const values = expected(c.points, own, aggregation, cmp.key, full, ys);
            if (!values || values[0] === null || values[1] === null) {
              expect(cmp.available, where).toBe(false);
              continue;
            }
            expect(cmp.available, where).toBe(true);
            expect(valueMismatch(cmp.current!, values[0], 2), where).toBeNull();
            expect(valueMismatch(cmp.previous!, values[1], 2), where).toBeNull();
            // The change, its percentage and whether it is good (#126): exact on the two values. Where both spans
            // end within 15 digits the values are exactly the spans', so the change is the exact one's nearest double.
            const change = referenceChangeOf(values[0], values[1], m.polarity);
            const shown = referenceChangeOf(exactOf(cmp.current!), exactOf(cmp.previous!), m.polarity);
            expect(isNearestDouble(cmp.abs!, shown.abs), `${where}: change ${cmp.abs}`).toBe(true);
            expect(shown.pct === null ? cmp.pct === null : isNearestDouble(cmp.pct!, shown.pct), `${where}: % ${cmp.pct}`).toBe(true);
            if (fitsDigits(values[0], 15) && fitsDigits(values[1], 15)) expect(valueMismatch(cmp.abs!, change.abs, 2), where).toBeNull();
            expect(cmp.good, where).toBe(change.good);
          }
        }
      }
    }
  });

  it("compares a weekly Metric's week with the week 52 weeks before", () => {
    const w = metric({ period: "week" });
    const [yoy] = compare(w, resolverFrom([w], { revenue: at(["2025-11-10", "2026-11-09"]) }), { yearStart: 1, keys: ["yoy"] });
    expect(yoy).toMatchObject({ available: true, current: 2.25, previous: 1.25, previousSpan: "Week of 10 Nov 2025" });
  });

  it("names a weekly Metric's month by the weeks it counts", () => {
    const w = metric({ period: "week" });
    const r = resolverFrom([w], { revenue: at(starts("2026-09-07", "week", 13, 1)) });
    // The latest week starts on 30 November 2026; November's weeks start on the 2nd and end with that one.
    const [toDate] = compare(w, r, { yearStart: 1, keys: ["mom"] });
    expect(toDate).toMatchObject({ currentSpan: "Week of 2 Nov 2026 to Week of 30 Nov 2026", previousSpan: "Week of 5 Oct 2026 to Week of 26 Oct 2026" });
    const [full] = compare(w, r, { yearStart: 1, keys: ["mom"], full: true });
    expect(full).toMatchObject({ currentSpan: "Week of 2 Nov 2026 to Week of 30 Nov 2026", previousSpan: "Week of 5 Oct 2026 to Week of 26 Oct 2026" });
    expect(exactText(exactOf(toDate.current!))).toBe(String(toDate.current));
  });
});

src/aggregations-targets.test.ts.source:
// Target Series combined against the reference on the hand-made cases (spec 0022; GLOSSARY: Target Series,
// Display Period), for every source Period, Display Period, Aggregation, polarity and Fiscal Year start.
import { describe, expect, it } from "vitest";
import { resolverFrom } from "./compare";
import { seriesBy, shownSeries, targetsBy } from "./display-periods";
import { canvas, metric } from "./test/fixtures";
import { at, everyCase, LATER, starts } from "./test/reference/cases";
import { longer, targetsMismatch } from "./test/reference/check";
import { referenceSeries, referenceTargets } from "./test/reference/combine";

describe("Target Series combined", () => {
  it("equals the reference on every hand-made case, with targets for some periods", () => {
    // Each case is read with one of the four kinds of target in turn, so every kind meets every source Period,
    // Display Period and Fiscal Year start across the cases without running each case four times.
    const kinds = [["higher", 100, null], ["lower", null, 5], ["target", 1, 2], ["higher", null, null]] as const;
    let n = 0;
    for (const { own, ys, c } of everyCase()) {
      // Targets for most periods, not all, so some spans have a whole Target Series and some do not.
      const targets = c.points.filter((_, i) => i % 5 !== 3).map((p, i) => ({ period: p.period, value: 0.1 * (i % 4) }));
      for (const aggregation of ["sum", "average", "last"] as const) {
        const m = metric({ period: own, aggregation });
        for (const display of longer(own)) {
          const opts = { yearStart: ys, today: c.today, alignTo: c.alignTo };
          const code = seriesBy(m, resolverFrom([m], { revenue: c.points }), display, opts);
          const ref = referenceSeries(c.points, own, display, aggregation, opts);
          if (!code.ok || !ref.ok) throw new Error("refused");
          {
            const [polarity, min, max] = kinds[n++ % kinds.length];
            const withTarget = { ...m, polarity, target_min: min, target_max: max };
            const wrong = targetsMismatch(targetsBy(withTarget, targets, code.points, display, ys), referenceTargets(targets, ref.spans, withTarget, ys));
            expect(wrong, `${c.name}: ${own} by ${display}, ${aggregation}, ${polarity}, ${ys}`).toBeNull();
          }
        }
      }
    }
  });

  it("adds three monthly targets of 0.1 to 0.3", () => {
    const m = metric();
    const points = at(starts("2026-01-01", "month", 3, 1));
    const s = shownSeries(m, canvas([m], { revenue: points }, { targets: { 1: at(starts("2026-01-01", "month", 3, 1), () => 0.1) } }), "quarter", { today: LATER });
    expect(s.targets?.line).toEqual([{ period: "2026-01-01", value: 0.3 }]);
  });
});

